type Order struct {
    ID         int64
    CustomerID sql.NullInt64
}

func (r *Repo) Order(id int64) (Order, error) {
    var o Order
    err := r.db.QueryRow("SELECT id, customer_id FROM orders WHERE id = $1", id).
        Scan(&o.ID, &o.CustomerID)   // key stays a key until you resolve it
    return o, err
}
